import { log } from '../core/fff.js';
import { BT } from './BT.js';
import { GameInput } from './GameInput.js';
import { ControlableEntity } from './ControlableEntity.js';

export class Player extends ControlableEntity {
    constructor(gameInput, texture, initialX = 0, initialY = 0) {
        super(gameInput, texture);

        this.x = initialX;
        this.y = initialY;

        this.anchor.x = this.anchor.y = .5;

        this._vx = 0;
        this._vy = 0;

        this._speed = 80;
    }

    upIsDown() { this._vy = -1 * this._speed; }
    upIsUp() { }
    upOnPress() { }
    upOnRelease() { }

    downIsDown() { this._vy = this._speed; }
    downIsUp() { }
    downOnPress() { }
    downOnRelease() { }

    leftIsDown() { this._vx = -1 * this._speed; }
    leftIsUp() { }
    leftOnPress() { }
    leftOnRelease() { }

    rightIsDown() { this._vx = this._speed; }
    rightIsUp() { }
    rightOnPress() { }
    rightOnRelease() { }

    action1IsDown() { log("Pressing Action 1"); }
    action1IsUp() { }
    action1OnPress() { }
    action1OnRelease() { BT.currentScreen.flash(0xFFFFFF); BT.currentScreen.playerAction(GameInput.ACTION1); }

    action2IsDown() { log("Pressing Action 2"); }
    action2IsUp() { }
    action2OnPress() { }
    action2OnRelease() { BT.currentScreen.flash(0xCC0000); }

    action3IsDown() { log("Pressing Action 3"); }
    action3IsUp() { }
    action3OnPress() { }
    action3OnRelease() { BT.currentScreen.shake(); }

    update(dt) {
        this.x += this._vx * dt;
        this.y += this._vy * dt;

        // easing
        this._vx *= .9;
        if (Math.abs(this._vx) < 1) {
            this._vx = .0;
        }

        this._vy *= .9;
        if (Math.abs(this._vy) < 1) {
            this._vy = .0;
        }
    }
}