import { Graphics, Text } from '../core/fff.js';
import { Config } from '../engine/Config.js';

export class HexOperations {
    constructor() { }

    /**
     * Desine un hexagone flat : 0°, 60°, 120°, 180°, 240°, 300° (par opposition a pointy)
     * @param {*} g Graphics, PIXI.Graphics
     * @param {*} pCenter Point
     * @param {*} pHexSize width of the grid
     * @param {*} pColor
     * @param {*} pLineWidth
     * @param {*} pAlpha
     */
    static drawHex(g, pCenter, pHexSize = 32, pColor = 0xDEDEDE, pLineWidth = 2, pAlpha = 1) {
        g.lineStyle(pLineWidth, pColor, pAlpha);
        let angle_rad = Math.PI / 180 * 0;
        g.moveTo(pCenter.x + pHexSize * Math.cos(angle_rad), pCenter.y + pHexSize * Math.sin(angle_rad));
        for (let i = 60; i <= 360; i += 60) {
            angle_rad = Math.PI / 180 * i;
            g.lineTo(pCenter.x + pHexSize * Math.cos(angle_rad), pCenter.y + pHexSize * Math.sin(angle_rad));
        }
    }

    /**
     * Ajoute un texte de debug sur un Hex
     * @param {*} g
     * @param {*} pCenter
     * @param {*} pDebug
     */
    static drawHexLabel(g, pCenter, pDebug = "?", dY = 0) {
        let text = new Text(pDebug, Config.base_style_12);
        text.anchor.set(.5, .5);
        text.position.set(pCenter.x, pCenter.y + dY);
        g.addChild(text);
    }


    /**
	 * Draw a grid in the target Graphics object
	 * @param {*} g Graphics, PIXI.Graphics
	 * @param {*} pMapSize size of the grid (same value for with and height)
	 * @param {*} pHexSize width of the grid
     * @param {*} pColor
     * @param {*} pLineWidth
     * @param {*} pAlpha
     *
     * pointy hex has   width = sqrt(3) * size (The sqrt(3) comes from sin(60°))
     * and              height = 2 * size
     * The horizontal distance between adjacent hexagon centers is w. The vertical distance between adjacent hexagon centers is h * 3/4.
     */
    static drawHexGrid(g, pHexGrid, pHexSize = 32, pColor = 0xDEDEDE, pLineWidth = 2, pAlpha = 1) {
        for (let cValue of Object.values(pHexGrid.map)) {
            this.drawHex(g, cValue.center(pHexSize), pHexSize, pColor, pLineWidth, pAlpha);
        }
    }

    static drawHexGridLabels(c, pHexGrid, pHexSize, pDy) {
        for (let [cKey, cValue] of Object.entries(pHexGrid.map)) {
            this.drawHexLabel(c, cValue.center(pHexSize), cKey, pDy);
        }
    }

    static drawHexPlot(g, pHex, pColor, pAlpha) {
        let shape = new Graphics();
        shape.beginFill(pColor, pAlpha);
        shape.drawCircle(0, 0, 6);
        shape.endFill();
        let lPoint = pHex.center(32);
        shape.x = lPoint.x;
        shape.y = lPoint.y;
        g.addChild(shape);

        return shape;
    }

    static drawHexVisibility(g, pHexgrid, pVisibilityMap, pColor = 0x0) {
        for (let cKey of Object.keys(pHexgrid.map)) {
            if (pHexgrid.walkable[cKey] == true) {
                if (pVisibilityMap[cKey]) {
                    pHexgrid.hexTiles[cKey].tint = pHexgrid.hexTiles[cKey].baseTint;
                } else {
                    pHexgrid.hexTiles[cKey].tint = pHexgrid.hexTiles[cKey].baseTint - pColor;
                }
            }
        }
    }

    static drawHexPath(g, pHexPath, pColor = 0xCC0000, pLineWidth = 2, pAlpha = 1, pOnlyPlots = false) {
        if (pHexPath.length > 0) {
            g.moveTo(pHexPath[0].x, pHexPath[0].y);
            for (let i = 0; i < pHexPath.length; i++) {
                let lHex = pHexPath[i];
                this.drawHexPlot(g, lHex, pColor, pAlpha);
                if (pLineWidth > 0 && pOnlyPlots == false) {
                    let lCenter = lHex.center(32);
                    g.lineStyle(pLineWidth, pColor, pAlpha);
                    g.lineTo(lCenter.x, lCenter.y);
                }
            }
        }
    }
}