import { Datas } from '../../engine/Datas.js';
import './HexDatas.js';
import { HexmapTest } from './HexmapTest.js';

const assets = [
    [Datas.BALL_GREEN, 'tps/green-ball.png'],

    [Datas.HEX_FLOOR_DIRT, 'hex/floor_dirt.png'],
    [Datas.HEX_FLOOR_GRASS, 'hex/floor_grass.png'],
    [Datas.HEX_FLOOR_STONE, 'hex/floor_stone.png'],

    [Datas.HEX_SKELETON_W, 'hex/skeleton_W.png'],
    [Datas.HEX_SKELETON_SW, 'hex/skeleton_SW.png'],
    [Datas.HEX_SKELETON_S, 'hex/skeleton_S.png'],
    [Datas.HEX_SKELETON_SE, 'hex/skeleton_SE.png'],
    [Datas.HEX_SKELETON_E, 'hex/skeleton_E.png'],
    [Datas.HEX_SKELETON_NE, 'hex/skeleton_NE.png'],
    [Datas.HEX_SKELETON_N, 'hex/skeleton_N.png'],
    [Datas.HEX_SKELETON_NW, 'hex/skeleton_NW.png']
];

// frames du squelette, dans l'ordre des 8 directions (voir Skeleton)
const init = () => {
    Datas.atlas[Datas.HEX_SKELETON_FRAMES] = [
        Datas.HEX_SKELETON_W, Datas.HEX_SKELETON_NW, Datas.HEX_SKELETON_N, Datas.HEX_SKELETON_NE,
        Datas.HEX_SKELETON_E, Datas.HEX_SKELETON_SE, Datas.HEX_SKELETON_S, Datas.HEX_SKELETON_SW
    ].map((key) => Datas.atlas[key]);
};

export const hex = { id: 'hex', title: 'Grille hexagonale', screen: HexmapTest, assets, init };
