import './HexDatas.js';
import { EventBroker } from '../../core/EventBroker.js';
import { MessageEvent } from '../../core/MessageEvent.js';
import { MovieClip, Point, bindPointerHandlers } from '../../core/fff.js';

export class Skeleton extends MovieClip {
    constructor(pFrames) {
        super(pFrames);
        this.frame = 0;
        this.dir = 0;
        this.lastDir;
        this.anchor.set(.5, .8);
        this.alpha = 1;

        // utile si on a des click/d&d etc.
        this.eventMode = 'static';
        bindPointerHandlers(this);
        this.isDrag = false;

        this.cursor = 'grab';
    }

    // cannot uglify : pointerdown = (pEvent) => {
    pointerdown(pEvent) {
        this.isDrag = true;
        this.cursor = 'grabbing';
    };


    pointerup(pEvent) {
        this.pointerupoutside(pEvent);
    }

    pointerupoutside(pEvent) {
        this.isDrag = false;
        this.cursor = 'grab';

        let me = new MessageEvent(MessageEvent.RELEASE_SKELETON, this);
        EventBroker.broadcast(me);
    }

    // globalpointermove (et non pointermove) : pendant un drag rapide le curseur sort du petit sprite,
    // et pointermove ne serait plus livre a cet objet (le drag se figerait)
    globalpointermove(pEvent) {
        if (this.isDrag) {
            this.position = pEvent.getLocalPosition(this.parent);
            let me = new MessageEvent(MessageEvent.MOVE_SKELETON, this);
            EventBroker.broadcast(me);
        }
    }

    moveToHex(pDestHex) {
        this.position = pDestHex.center();
    }

    // entre 0 et 15?
    lookAtPoint(pPoint) {
        let angle = Math.atan2(pPoint.y - this.y, pPoint.x - this.x);
        angle *= 180 / Math.PI;
        let sliceAngleDegres = 22.5; // donne des resultats entre -7 et 7 du coup on ajoute 7 pour indexer ça sur un tableau de frame (le /2 c'est pour donner 2 slices à une direction)
        this.dir = angle / sliceAngleDegres < 0 ? 16 + Math.round(angle / sliceAngleDegres) : Math.round(angle / sliceAngleDegres);
        // le modulo ramene les angles proches de +180 (index 8) sur la frame 0 : le squelette n'a que 8 frames
        let lFrame = (Math.floor((Math.floor(angle / sliceAngleDegres) + 7) / 2) + 1) % this.totalFrames;
        if (this.currentFrame != lFrame) {
            this.frame = lFrame;
            this.gotoAndStop(this.frame);
        }
    }

    lookAtHex(pHex) {
        this.lookAtPoint(pHex.center(32));
    }

    lookAtDir(pDir) {
        if (pDir < 0 || pDir > 15) {
            pDir = 0;
        }
        let sliceAngleDegres = 22.5;
        let alpha = (pDir * sliceAngleDegres) * Math.PI / 180;
        let point = new Point(this.x + Math.cos(alpha), this.y + Math.sin(alpha));
        this.lookAtPoint(point);
    }

    lookAtRandomDir(pRan = null) {
        if (pRan) {
            this.lookAtDir(Math.floor(pRan.next() * 16));
        } else {
            this.lookAtDir(Math.floor(Math.random() * 16));
        }
    }
}