import './HexDatas.js';
import '../../lib/pixi.js';
import { MessageEvent } from '../../core/MessageEvent.js';
import { Container, Graphics, Sprite } from '../../core/fff.js';
import { BT } from '../../engine/BT.js';
import { BaseScreen } from '../../engine/BaseScreen.js';
import { Config } from '../../engine/Config.js';
import { Datas } from '../../engine/Datas.js';
import { Player } from '../../engine/Player.js';
import { Skeleton } from './Skeleton.js';
import { HexGrid } from '../../utils/HexGrid.js';
import { HexOperations } from '../../utils/HexOperations.js';

export class HexmapTest extends BaseScreen {
    constructor() {
        super();
    }

    start() {
        this._nextScreen = HexmapTest;
        this.ran = BT.createSeededGenerator(123456);

        super.start();
        this.visible = true;
        this.hexTiles = {};
        this.showResult = true;


        BT.stage.addChildAt(Datas.atlas[Datas.BACKGROUND_IMAGE], 0);

        // the main game container
        let container = this.stage.addChild(new Container());

        ///////////////////////////
        // HEX MAP

        let MAP_SIZE = this.MAP_SIZE = 10;
        // create graphics container and tiles tints
        let hexContainer = this.hexContainer = new Container();
        hexContainer.scale.set(.7, .7);

        // create the Hex grid
        let hexGrid = this.hexGrid = new HexGrid();
        hexGrid.generate(MAP_SIZE);

        // add some obstacles
        hexGrid.generateRandomWalls(30, this.ran);
        let tints = [0xFEFEFE, 0xEFEFEF, 0xDEDEDE, 0xCECECE];
        for (let [cKey, cValue] of Object.entries(hexGrid.map)) {
            let lCenter = cValue.center(32);
            let sp = new Sprite(Datas.atlas[Datas.HEX_FLOOR_STONE]);
            if (hexGrid.isHexWalkable(cKey)) {
                if (this.ran) {
                    this.ran.next(); // fait avancer le generateur seede (sa valeur n'est pas utilisee ici)
                }
                sp.baseTint = tints[Math.floor(this.ran.next() * tints.length)];
            } else {
                sp.baseTint = 0x606060;
                sp.tint = sp.baseTint;
            }
            sp.width = 66;
            sp.height = 57;
            sp.anchor.set(0.5, 0.5);
            sp.position.set(lCenter.x, lCenter.y);
            hexContainer.addChild(sp);
            hexGrid.hexTiles[cKey] = sp; // on sauve les ref des tuiles
        }

        let hexGridGraphics = this.hexGridGraphics = new Graphics();
        hexContainer.addChild(hexGridGraphics);

        let hexGridLabelContainer = this.hexGridLabelContainer = new Container();
        hexContainer.addChild(hexGridLabelContainer);

        let hexPathGraphics = this.hexPathGraphics = new Graphics();
        hexContainer.addChild(hexPathGraphics);

        let hexRayGraphics = this.hexRayGraphics = new Graphics();
        hexContainer.addChild(hexRayGraphics);

        let skeleton1 = this.skeleton1 = new Skeleton(Datas.atlas[Datas.HEX_SKELETON_FRAMES]);
        hexContainer.addChild(skeleton1);

        hexContainer.position.set(Config.STAGEWIDTH2 - 80, 380);
        container.addChild(hexContainer);

        // player
        let player = this.player = new Player(this.gameInput1, Datas.atlas[Datas.BALL_GREEN], 0, 0);
        player.position.set(0, 166.3409735838936);
        hexContainer.addChild(player);

        // pose un squelette 8-way
        let skeletonOriHex = this.skeletonOriHex = this.hexGrid.getByXY(0, 0);
        skeleton1.moveToHex(skeletonOriHex);
        skeleton1.lookAtPoint(this.player.position);

        this.subscribe(MessageEvent.MOVE_SKELETON, (me) => {
            let target = me.datas;
            let hex = this.hexGrid.getHexFromPoint(target.position);
            if (this.hexGrid.isHexWalkable(hex)) {
                this.showResult = true;
                this.skeletonOriHex = hex;
            } else {
                this.showResult = false;
            }
        });

        this.subscribe(MessageEvent.RELEASE_SKELETON, (me) => {
            let target = me.datas;
            let hex = this.hexGrid.getHexFromPoint(target.position);
            if (this.hexGrid.isHexWalkable(hex)) {
                this.skeletonOriHex = hex;
                target.moveToHex(hex);
                this.playerHitSpace();
            }
        });

        ///////////////////////////
        // DRAW HEXGRID
        this.hexGridGraphics.clear();
        while (this.hexGridGraphics.children.length > 0) {
            this.hexGridGraphics.removeChildAt(0);
        }
        this.hexPathGraphics.clear();
        while (this.hexPathGraphics.children.length > 0) {
            this.hexPathGraphics.removeChildAt(0);
        }
        this.hexRayGraphics.clear();
        while (this.hexRayGraphics.children.length > 0) {
            this.hexRayGraphics.removeChildAt(0);
        }
        HexOperations.drawHexGrid(this.hexGridGraphics, this.hexGrid, 32, 0x333333);
        HexOperations.drawHexGridLabels(this.hexGridLabelContainer, this.hexGrid, 32, 10);

        ///////////////////////////////////////////
        // Tick
        BT.ticker.start();

        //
        this.playerHitSpace();
    }

    playerHitSpace() {
        this.hexRayGraphics.clear();
        while (this.hexRayGraphics.children.length > 0) {
            this.hexRayGraphics.removeChildAt(0);
        }

        ///////////////////////////
        // RAYS et FOV
        if (this.showResult) {
            HexOperations.drawHexVisibility(
                this.hexRayGraphics,
                this.hexGrid,
                this.hexGrid.getFov(
                    this.skeletonOriHex,
                    this.skeleton1.dir,
                    this.MAP_SIZE - 1,
                    9),
                0x444400
            );
        } else {
            HexOperations.drawHexVisibility(
                this.hexRayGraphics,
                this.hexGrid,
                {},
                0x444400
            );
        }

    }

    onEnterFrame(pDt) {
        // update player inputs
        this.gameInput1.update(pDt);

        // update du player

        this.player.update(pDt);

        let speed = Math.abs(this.player._vx + this.player._vy);
        let playerHex = this.hexGrid.getHexFromPoint(this.player.position);
        if (speed > 0 && speed < 3) {
            if (this.hexGrid.isHexWalkable(playerHex)) {
                this.player.position = playerHex.center();
            }
        }


        if (this.hexGrid.isValidHex(playerHex)) {
            if (this.hexGrid.hexVisibility[playerHex.toString()]) {
                this.skeleton1.lookAtPoint(this.player.position);
                if (this.skeleton1.dir != this.skeleton1.lastDir) {
                    this.skeleton1.lastDir = this.skeleton1.dir;
                    this.playerHitSpace();
                }
                this.player.alpha = 1;
            } else {
                this.player.alpha = 1 / 3;
            }
        } else {
            this.player.alpha = 1;
        }

        if (this.player.x < -750) { this.player.x += 1500 }
        if (this.player.x > 750) { this.player.x -= 1500 }
        if (this.player.y < -750) { this.player.y += 1500 }
        if (this.player.y > 750) { this.player.y -= 1500 }
    };
}