import { Point } from '../core/fff.js';

// col(q)
// row(r)
// https://www.redblobgames.com/grids/hexagons/#coordinates-offset

export class Hex {
    constructor(pQ, pR, pS) {
        this.q = pQ;
        this.r = pR;
        this.s = pS;
        if (Math.round(this.q + this.r + this.s) !== 0)
            throw "pQ + pR + pS doit être égal à 0";
    }

    toString() {
        return this.q + "_" + this.r + "_" + this.s;
    }

    add(b) {
        return new Hex(this.q + b.q, this.r + b.r, this.s + b.s);
    }

    subtract(b) {
        return new Hex(this.q - b.q, this.r - b.r, this.s - b.s);
    }

    scale(k) {
        return new Hex(this.q * k, this.r * k, this.s * k);
    }

    rotateLeft() {
        return new Hex(-this.s, -this.q, -this.r);
    }

    rotateRight() {
        return new Hex(-this.r, -this.s, -this.q);
    }

    static direction(direction) {
        return Hex.directions[direction];
    }

    neighbor(direction) {
        return this.add(Hex.direction(direction));
    }

    diagonalNeighbor(direction) {
        return this.add(Hex.diagonals[direction]);
    }

    len() {
        return (Math.abs(this.q) + Math.abs(this.r) + Math.abs(this.s)) / 2;
    }

    distance(b) {
        return this.subtract(b).len();
    }

    round(i) {
        // plus la listance est grande plus l'erreur grandie
        //
        let err = 1e-06;
        if (i == 2) {
            err *= 2;
        }
        // a jusqu'a 8 cases ça va bien !
        if (i < 8) {
            i = i + 1;
        }

        if (this.q > 0) {
            this.q -= err * (i - 1);
        } else {
            this.q += err * (i - 1);
        }

        let qi = Math.round(this.q);

        let ri = Math.round(this.r);
        if (this.r > 0) {
            this.r -= err * (i - 1);
        } else {
            this.r += err * (i - 1);
        }

        let si = Math.round(this.s);
        if (this.s > 0) {
            this.s -= err * (i - 1);
        } else {
            this.s += err * (i - 1);
        }

        let q_diff = Math.abs(qi - this.q);
        let r_diff = Math.abs(ri - this.r);
        let s_diff = Math.abs(si - this.s);

        if (q_diff > r_diff && q_diff > s_diff) {
            qi = -ri - si;
        }
        else if (r_diff > s_diff) {
            ri = -qi - si;
        }
        else {
            si = -qi - ri;
        }

        return new Hex(qi, ri, si);
    }

    lerp(b, t) {
        return new Hex(this.q * (1.0 - t) + b.q * t, this.r * (1.0 - t) + b.r * t, this.s * (1.0 - t) + b.s * t);
    }

    linedraw(b) {
        let N = this.distance(b);
        let a_nudge = new Hex(this.q, this.r, this.s);
        let b_nudge = new Hex(b.q, b.r, b.s);
        let results = [];
        let step = 1.0 / Math.max(N, 1);
        for (let i = 0; i <= N; i++) {
            results.push(a_nudge.lerp(b_nudge, step * i).round(i));
        }
        return results;
    }

    center(pHexSize = 32) {
        let hh = Math.sqrt(3) * pHexSize;
        let hh2 = hh / 2;
        let ww = pHexSize * 2 * (3 / 4);

        return new Point(this.q * ww, (this.s * hh) + (this.q * hh2));
    }

    equals(pOtherHex) {
        return (this.q === pOtherHex.q) && (this.r === pOtherHex.r) && (this.s === pOtherHex.s);
    }

    clone() {
        return new Hex(this.q, this.r, this.s);
    }
}
// OK
Hex.directions = [new Hex(1, 0, -1), new Hex(1, -1, 0), new Hex(0, -1, 1), new Hex(-1, 0, 1), new Hex(-1, 1, 0), new Hex(0, 1, -1)];
// OK
Hex.diagonals = [new Hex(2, -1, -1), new Hex(1, -2, 1), new Hex(-1, -1, 2), new Hex(-2, 1, 1), new Hex(-1, 2, -1), new Hex(1, 1, -2)];