import { PriorityQueue } from '../core/PriorityQueue.js';
import { Point } from '../core/fff.js';
import { BT } from '../engine/BT.js';
import { Hex } from './Hex.js';

export class HexGrid {

    constructor() {
        this.map = {};
        this.walkable = {}; // chaque hexagone est walkable par défeaut
        this.size = 0;
        this.hexTiles = {}; // la colelction de tuiles
        this.hexVisibility = {};
    }

    /**
     * taille de la grid (rayon autour du centre)
     * @param {*} pSize
     */
    generate(pSize) {
        this.size = pSize;
        for (let col = -pSize; col <= pSize; col++) {
            for (let row = -pSize; row <= pSize; row++) {
                let dist = this.calcCubeDistance(new Point(col, row), new Point(0, 0));
                if (dist < pSize) {
                    this.add(new Hex(col, row, -col - row));
                }
            }
        }
    }

    /**
     * Distance cubique entre 2 hex
     * @param {*} pA
     * @param {*} pB
     */
    calcCubeDistance(pA, pB) {
        return (Math.abs(pA.x - pB.x) + Math.abs(pA.y - pB.y) + Math.abs(-pA.x - pA.y - pB.x - pB.y)) / 2;
    }

    /**
     * Genere une liste de murs infranchissables
     * @param {*} pNbWalls
     */
    generateRandomWalls(pNbWalls, pRan) {
        for (let w = 0; w < pNbWalls; w++) {
            this.setHexIsWalkable(this.getWalkableHexRandom(pRan), false);
        }
    }

    /**
     * ajoute un hexagone à la map et dans la walk map
     * @param {*} pHex
     */
    add(pHex) {
        this.map[pHex.toString()] = pHex;
        this.walkable[pHex.toString()] = true;
    }

    /**
     * get un Hexagone ligne/colone
     * @param {*} pX
     * @param {*} pY
     */
    getByXY(pX, pY) {
        let hex = new Hex(pX, pY, -pX - pY); // just to get the string
        return this.get(hex.toString());
    }

    getHexFromPoint(pPoint, pSize = 32) {
        let hh = Math.sqrt(3) * pSize;
        let hh2 = hh / 2;
        let ww = pSize * 2 * (3 / 4);
        let q = Math.round(pPoint.x / ww);
        let s = Math.round((pPoint.y - q * hh2) / hh);
        let hex = new Hex(q, -q - s, s);
        if (this.isValidHex(hex)) {
            return this.get(hex.toString());
        }
        return null;
    }

    /**
     * prend un hexagone de la map au hasard
     */
    getRandom(pRan = null) {
        var keys = Object.keys(this.map);
        let ran = Math.random();
        if (pRan) {
            ran = pRan.next();
        }
        return this.map[keys[Math.floor(ran * keys.length)]];
    }

    /**
     * prend un hexagone walkable au hasard
     */
    getWalkableHexRandom(pRan = null) {
        var keys = Object.keys(this.walkable);
        let key;
        let isWalkable = false;
        while (!isWalkable) {
            let ran = Math.random();
            if (pRan) {
                ran = pRan.next();
            }
            key = keys[Math.floor(ran * keys.length)];
            isWalkable = this.walkable[key];
        }
        return this.map[key];
    }

    /**
     * renvoi une liste d'hexagone sur une ligne
     * @param {*} pHexStart
     * @param {*} pHexEnd
     */
    getHexLineFromTo(pHexStart, pHexEnd) {
        return pHexStart.linedraw(pHexEnd);
    }

    /**
     * renvoi une liste d'hexagone sur un rayon (stoppe sur un obstacle)
     * @param {*} pHexStart
     * @param {*} pHexEnd
     */
    getHexRayFromTo(pHexStart, pHexEnd) {
        let hexLine = pHexStart.linedraw(pHexEnd);
        let hexRay = [];
        for (let index = 0; index < hexLine.length; index++) {
            let hex = hexLine[index];
            if (this.isHexWalkable(hex)) {
                hexRay.push(hex);
            } else {
                return hexRay;
            }
        }
        return hexRay;
    }

    getFov(pHexStart, pDirection, pLimitMax, pLimit) {
        let visible = {};
        pLimitMax = Math.abs(pLimitMax);
        if (pLimit > pLimitMax) {
            pLimit = pLimitMax;
        }

        // on determine le périmètre de tir
        let ray = this.getHexLine(pHexStart, pDirection); // attention, ignore les obstacles
        let targetHex = ray.pop();
        let limits = {};
        limits[targetHex.toString()] = targetHex;

        let lastHex = null;
        let lastHexes = [];
        for (let dir = 0; dir < 6; dir++) {
            let neighbor = targetHex.neighbor(dir);
            while (
                this.isValidHex(neighbor)
                && (Math.abs(neighbor.q) == pLimitMax || Math.abs(neighbor.r) == pLimitMax || Math.abs(neighbor.s) == pLimitMax)
                && limits[neighbor.toString()] == undefined) {
                limits[neighbor.toString()] = neighbor;
                lastHex = neighbor;
                neighbor = neighbor.neighbor(dir);
            }
            if (lastHex) {
                lastHexes.push(lastHex);
                lastHex = null;
            }
        }

        if (pDirection < 10 && pDirection > 1) {
            lastHexes.reverse();
        }

        // rayon 1
        let limit1 = targetHex.clone().rotateLeft();
        if (limits[limit1.toString()] == undefined) {
            limits[limit1.toString()] = limit1;
            for (let dir = 0; dir < 6; dir++) {
                let neighbor = lastHexes[0].neighbor(dir);
                while (
                    this.isValidHex(neighbor)
                    && (Math.abs(neighbor.q) == pLimitMax || Math.abs(neighbor.r) == pLimitMax || Math.abs(neighbor.s) == pLimitMax)
                    && limits[neighbor.toString()] == undefined) {
                    limits[neighbor.toString()] = neighbor;
                    neighbor = neighbor.neighbor(dir);
                }
            }
        }

        // rayon 2
        let limit2 = targetHex.clone().rotateRight();
        if (limits[limit2.toString()] == undefined) {
            limits[limit2.toString()] = limit2;
            for (let dir = 0; dir < 6; dir++) {
                let neighbor = lastHexes[1].neighbor(dir);
                while (
                    this.isValidHex(neighbor)
                    && (Math.abs(neighbor.q) == pLimitMax || Math.abs(neighbor.r) == pLimitMax || Math.abs(neighbor.s) == pLimitMax)
                    && limits[neighbor.toString()] == undefined) {
                    limits[neighbor.toString()] = neighbor;
                    neighbor = neighbor.neighbor(dir);
                }
            }
        }

        // on lance les rayons (les rayons cognent les obstacles)
        for (let cValue of Object.values(limits)) {
            let result = this.getHexRayFromTo(pHexStart, cValue);
            if (result.length > pLimit) {
                result.length = pLimit;
            }
            for (let h = 0; h < result.length; h++) {
                visible[result[h].toString()] = result[h];
            }
        }

        this.hexVisibility = visible;

        return visible;
    }

    /**
     * Traverse les obstacles
     * Limite de taille arbitraire de rayInc * limit
     * @param {*} pHexStart
     * @param {*} pDirection
     * @param {*} pLen
     */
    getHexLine(pHexStart, pDirection, g = null /*, pLen = -1*/) {
        let rayInc = 33; // 10
        let startCenter = pHexStart.center();
        let currPosition = new Point(startCenter.x, startCenter.y);
        let sliceAngleDegres = 22.5;
        let alphaRad = (pDirection * sliceAngleDegres) * Math.PI / 180;
        let isWalking = true;
        let limit = 99; // 100
        let it = 0;
        if (g) {
            g.lineStyle(2, 0xCCCC00, 1 / 3);
            g.moveTo(currPosition.x, currPosition.y);
        }
        while (isWalking) {
            let nextPoint = new Point(currPosition.x + (Math.cos(alphaRad) * rayInc), currPosition.y + (Math.sin(alphaRad) * rayInc));
            let nextHex = this.getHexFromPoint(nextPoint);
            isWalking = this.isValidHex(nextHex);
            if (isWalking == false || it++ > limit) {
                return pHexStart.linedraw(this.getHexFromPoint(currPosition));
            } else {
                if (g) {
                    g.lineTo(nextPoint.x, nextPoint.y);
                }
                currPosition = nextPoint;
            }
        }
        return [];
    }

    getHexRing(pHexOrigin, pRadius, pOnlyWalkable = false) {
        let result = [];
        if (pRadius < 1) {
            return result;
        }
        if (this.isValidHex(pHexOrigin)) {
            let hex = pHexOrigin.neighbor(0).subtract(new Hex(pRadius + 1, -pRadius, -1));
            for (let side = 0; side < 6; side++) {
                for (let step = 0; step < pRadius; step++) {
                    if (pOnlyWalkable) {
                        if (this.isHexWalkable(hex)) {
                            result.push(hex);
                        }
                    } else {
                        if (this.isValidHex(hex)) {
                            result.push(hex);
                        }
                    }
                    hex = hex.neighbor(side);
                }
            }
        }

        return result;
    }

    getHexDisc(pHexOrigin, pRadius, pOnlyWalkable = false) {
        let result = [];
        for (let i = pRadius; i > 0; i--) {
            result = result.concat(this.getHexRing(pHexOrigin, i, pOnlyWalkable));
        }
        result.push(pHexOrigin);
        return result;
    }

    /**
     * setter
     * @param {*} pHex
     * @param {*} pValue
     */
    setHexIsWalkable(pHex, pValue) {
        if (this.isValidHex(pHex)) {
            this.walkable[pHex.toString()] = pValue;
        }
    }

    /**
     * getter
     * @param {*} pHex
     */
    isHexWalkable(pHex) {
        if (this.isValidHex(pHex)) {
            return this.walkable[pHex.toString()];
        }
        return false;
    }

    /**
     *
     * @param {*} pHex
     */
    isValidHex(pHex) {
        if (pHex == null) {
            return false;
        }
        return !!this.map[pHex.toString()];
    }

    /**
     *
     * @param {*} pHash
     */
    get(pHash) {
        return this.map[pHash];
    }

    /**
     *
     * @param {*} pHexStart
     */
    breadthFirstSearch(pHexStart, pHexEnd = null) {
        let cost_so_far = {}; cost_so_far[pHexStart] = 0;
        let came_from = {}; came_from[pHexStart] = null;

        if (this.isHexWalkable(pHexStart)) {
            let fringes = [[pHexStart]];
            for (let k = 0; fringes[k].length > 0; k++) {
                fringes[k + 1] = [];
                for (let hex of fringes[k]) {
                    for (let dir = 0; dir < 6; dir++) {
                        let neighbor = hex.neighbor(dir);
                        if (cost_so_far[neighbor] === undefined
                            && this.isHexWalkable(neighbor)) {
                            cost_so_far[neighbor] = k + 1;
                            came_from[neighbor] = hex;
                            fringes[k + 1].push(neighbor);
                            // early exit
                            if (pHexEnd && neighbor.equals(pHexEnd)) {
                                return { cost_so_far, came_from };
                            }
                        }
                    }
                }

            }
        }
        return { cost_so_far, came_from };
    }

    getAStar(start, goal) {
        let frontier = new PriorityQueue();
        frontier.put(start, 0);
        let came_from = {};
        let cost_so_far = {};
        came_from[start] = null;
        cost_so_far[start] = 0;
        let goalCenter = goal.center(32);

        let current;
        while (!frontier.empty()) {
            current = frontier.get().element;

            if (current.equals(goal)) {
                return { cost_so_far, came_from };
            }

            for (let dir = 0; dir < 6; dir++) {
                let neighbor = current.neighbor(dir);
                if (this.isHexWalkable(neighbor)) {
                    let new_cost = cost_so_far[current] + Math.floor(BT.distance(current.center(32), neighbor.center(32)));
                    if (cost_so_far[neighbor] == null || new_cost < cost_so_far[neighbor]) {
                        cost_so_far[neighbor] = new_cost;
                        let priority = new_cost + Math.floor(BT.distance(goalCenter, neighbor.center(32)));
                        frontier.put(neighbor, priority);
                        came_from[neighbor] = current;
                    }
                }
            }
        }
    }

    simpleBackTrack(pGraph, pHexStart, pHexEnd) {
        let current = pHexEnd;
        let path = [];

        while (!current.equals(pHexStart)) {
            path.push(current);
            if (pGraph) {
                current = pGraph.came_from[current];
            } else {
                return [];
            }
        }
        path.push(pHexStart);

        return path.reverse();
    }

    getVisibleHexFrom(pHexStart, pDist) {
        let visible = {};
        for (let cValue of Object.values(this.map)) {
            if (
                (Math.abs(cValue.q) == pDist || Math.abs(cValue.r) == pDist || Math.abs(cValue.s) == pDist)
                && !cValue.equals(pHexStart)
            ) {
                let result = this.getHexRayFromTo(pHexStart, cValue);
                for (let i = 0; i < result.length; i++) {
                    visible[result[i].toString()] = true;
                }
            }
        }
        // on retire la case de départ du résultat
        return visible;
    }

    getVisible2HexFrom(pHexStart, pDist, pDirection) {
        let visible = {};
        for (let cValue of Object.values(this.map)) {
            if (
                (Math.abs(cValue.q) <= pDist || Math.abs(cValue.r) <= pDist || Math.abs(cValue.s) <= pDist)
                && !cValue.equals(pHexStart)
            ) {
                let result = this.getHexRayFromTo(pHexStart, cValue);
                for (let i = 0; i < result.length; i++) {
                    visible[result[i].toString()] = true;
                }
            }
        }
        // on retire la case de départ du résultat
        return visible;
    }

    getHiddenHexFrom(pHexStart, pDist) {
        let invisible = {};
        const visible = this.getVisibleHexFrom(pHexStart, pDist);
        for (let [cKey, cValue] of Object.entries(this.map)) {
            if (!visible[cKey] && this.isHexWalkable(cValue)) {
                invisible[cKey] = true;
            }
        }
        return invisible;
    }

    // -1 c'est full 360 ! sinon c'est un angle a 180°
    getHidden2HexFrom(pHexStart, pDist, pDirection = -1) {
        let invisible = {};
        const visible = this.getVisible2HexFrom(pHexStart, pDist, pDirection);
        for (let [cKey, cValue] of Object.entries(this.map)) {
            if (!visible[cKey] && this.isHexWalkable(cValue)) {
                invisible[cKey] = true;
            }
        }
        return invisible;
    }
}
